-range\": \"node smoke/dsh-peer-range-smoke.mjs\",\n    \"smoke:mcp-transport\": \"node smoke/dsh-mcp-transport-smoke.mjs\",\n    \"smoke:install\": \"node smoke/dsh-installer-smoke.mjs\",\n    \"smoke:registry\": \"node smoke/dsh-registry-smoke.mjs\",\n    \"verify:distribution\": \"node scripts/verify-distribution.mjs\",\n    \"smoke:profile\": \"node smoke/dsh-profile-smoke.mjs\",\n    \"smoke:runtime\": \"node smoke/dsh-goalbar-runtime-smoke.mjs\",\n    \"smoke:docker\": \"bash smoke/dsh-clean-docker-smoke.sh\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-renderer\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.2\",\n    \"@deepseek-ai/dsh\": \">=0.1.5-rc.1 <0.2.0-0 || >=0.1.7-rc.2 <0.1.7 || >=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.1 <0.2.1\",\n    \"@deepseek-ai/dsh-client-connection\": \">=0.1.5-rc.1 <0.2.0-0 || >=0.1.7-rc.2 <0.1.7 || >=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.1 <0.2.1\",\n    \"@deepseek-ai/dsh-client-locale\": \">=0.1.5-rc.1 <0.2.0-0 || >=0.1.7-rc.2 <0.1.7 || >=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.1 <0.2.1\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \">=0.1.5-rc.1 <0.2.0-0 || >=0.1.7-rc.2 <0.1.7 || >=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.1 <0.2.1\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \">=0.1.5-rc.1 <0.2.0-0 || >=0.1.7-rc.2 <0.1.7 || >=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.1 <0.2.1\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \">=0.1.5-rc.1 <0.2.0-0 || >=0.1.7-rc.2 <0.1.7 || >=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.1 <0.2.1\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \">=0.1.5-rc.1 <0.2.0-0 || >=0.1.7-rc.2 <0.1.7 || >=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.1 <0.2.1\",\n    \"react\": \"^18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": { \"optional\": true },\n    \"@deepseek-ai/dsh\": { \"optional\": true },\n    \"@deepseek-ai/dsh-client-connection\": { \"optional\": true },\n    \"@deepseek-ai/dsh-client-locale\": { \"optional\": true },\n    \"@deepseek-ai/dsh-client-ui-conversation\": { \"optional\": true },\n    \"@deepseek-ai/dsh-client-ui-primitives\": { \"optional\": true },\n    \"@deepseek-ai/dsh-client-ui-renderer\": { \"optional\": true },\n    \"@deepseek-ai/dsh-client-ui-slots\": { \"optional\": true },\n    \"react\": { \"optional\": true }\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.5\",\n    \"@deepseek-ai/dsh\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-agent\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-connection\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-commands\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-session\": \"0.2.1-rc.2\",\n    \"@types/node\": \"^22.19.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"~18.3.1\",\n    \"jsdom\": \"^26.1.0\",\n    \"lightningcss\": \"1.33.0\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\",\n    \"semver\": \"7.8.5\",\n    \"tsdown\": \"0.22.2\",\n    \"typescript\": \"^6.0.3\",\n    \"vitest\": \"^4.1.12\"\n  },\n  \"pnpm\": {\n    \"overrides\": {\n      \"@deepseek-ai/libreoffice-kit>fflate\": \"0.8.3\",\n      \"@modelcontextprotocol/client@<2.3.0\": \"2.3.0\",\n      \"@modelcontextprotocol/sdk@<1.32.0\": \"1.32.0\",\n      \"fast-uri@>=3.0.0 <3.1.8\": \"3.1.8\",\n      \"vite@>=8.2.0 <=8.2.3\": \"8.2.4\"\n    }\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/loopx-project/loopx.git\",\n    \"directory\": \"packages/dsh-loopx-plugin\"\n  },\n  \"license\": \"Apache-2.0\",\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"keywords\": [\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"loopx\",\n    \"workflow\",\n    \"goal\"\n  ],\n  \"homepage\": \"https://github.com/loopx-project/loopx/tree/main/packages/dsh-loopx-plugin\",\n  \"bugs\": {\n    \"url\": \"https://github.com/loopx-project/loopx/issues\"\n  }\n}\n"
